+  beforeEach(() => {
+    mockPush.mockReset();
+    mockReplace.mockReset();
+    mockFetchMe.mockReset();
+    mockLogoutFn.mockReset();
+  });
+
+  afterEach(() => {
+    vi.clearAllMocks();
+  });
+
